import Image from "next/image";
import { FlipSentences } from "@/components/flip-sentences";
import { PronounceName } from "@/components/pronounce-name";
import { site } from "@/lib/site";

/** "Dhruv Sharma" → "DS". */
function initials(name: string): string {
  return name
    .split(/\s+/)
    .slice(0, 2)
    .map((word) => word[0]?.toUpperCase() ?? "")
    .join("");
}

/**
 * The portrait slot is a monogram plate, not a gap waiting to be filled: with
 * no photograph set it draws the initials in the display face, so the slot
 * reads as a mark of its own rather than as a missing image.
 *
 * 128px on a phone, 160px on desktop — the portrait is one of the two things
 * the hero is for, so it is sized to hold the row rather than to sit politely
 * beside the name.
 */
function Avatar() {
  return (
    <div className="relative m-0.5 size-32 overflow-hidden rounded-xl border border-line bg-muted ring-1 ring-border/50 select-none sm:size-40">
      {site.avatar ? (
        <Image
          src={site.avatar}
          alt={site.name}
          fill
          sizes="(min-width: 640px) 160px, 128px"
          priority
          className="object-cover"
        />
      ) : (
        <span
          role="img"
          aria-label={`${site.name}, monogram`}
          className="absolute inset-0 grid place-items-center"
        >
          {/* A mount inset from the plate edge, like the figures elsewhere
              carry — the monogram is a mark this site drew, not a photograph
              that failed to load, and it should look like it was meant. */}
          <span
            aria-hidden
            className="absolute inset-2 rounded-md border border-line"
          />
          <span
            aria-hidden
            className="relative font-heading text-5xl font-medium tracking-tight text-foreground sm:text-6xl"
          >
            {initials(site.name)}
          </span>
        </span>
      )}
    </div>
  );
}

/**
 * The hero is a four-cell frame rather than a stacked block: the monogram sits
 * in its own gutter column, and the name and role stack against the bottom
 * edge so both meet one baseline. Nothing here is centred.
 *
 * The upper plate is deliberately blank — cleared down to the sheet, waiting
 * on what goes there next.
 */
export function ProfileHeader() {
  return (
    <div className="screen-line-bottom relative grid grid-cols-[auto_1fr] grid-rows-[1fr_auto] overflow-y-clip border-x border-line">
      {/* Empty on purpose. The cell keeps the hero's proportions so the frame
          below it does not ride up to the header; it holds nothing else. */}
      <div
        aria-hidden
        className="col-span-2 aspect-[556/354] w-full bg-red-500 sm:col-span-1 sm:col-start-2"
      />

      <div className="flex flex-col sm:row-span-2 sm:row-start-1">
        <div aria-hidden className="flex-1 bg-red-500" />
        <div className="screen-line-top shrink-0 border-r border-line">
          <Avatar />
        </div>
      </div>

      <div className="flex flex-col">
        <div className="z-1 mt-auto border-t border-line">
          <h1 className="-translate-y-px flex items-center gap-2 pl-4 text-[2rem]/none font-medium tracking-tight">
            {site.name}
            {/* Inside the heading, not beside it: the button is about this
                name, and a name and the way to hear it are one object. */}
            <PronounceName />
          </h1>
          {/* The one line that reads as a caption rather than as prose, so it
              is set in mono at the small size — and swept once on arrival,
              which is the reference's own way of pointing at it without
              shouting. */}
          <FlipSentences
            sentences={site.flipSentences}
            className="h-12.5 border-t border-line py-1 pl-4 font-mono text-sm text-balance text-muted-foreground sm:h-9"
          />
        </div>
      </div>
    </div>
  );
}
