import type { DailyTokens } from "@/lib/ai-activity";
import { buildTokenRidge, RIDGE_VIEWBOX } from "@/lib/token-ridge";
import { cn } from "@/lib/utils";

/**
 * The record drawn as a range, for the hero's figure plate.
 *
 * The plate is a window on a shape, not a chart: there is no axis, no rule and
 * no tick, because a silhouette that has to be measured off the page is a chart
 * pretending to be a picture. The exact quantities are one panel down, in Fig.
 * 2, which is what licenses the drawing to carry none.
 *
 * One silhouette, one crest, one ground line. The fill is a flat tint mixed off
 * the ink and the page rather than a fade, because a gradient here would be the
 * only one on the site; the crest is a hairline at the same weight as every
 * rule around it, so the drawing is made of the page's own marks.
 *
 * `preserveAspectRatio="none"` because the figure is normalised: the ridge
 * fills the plate at every width instead of letterboxing inside it. The only
 * thing that must survive that stretch is the line, and it carries
 * `vector-effect` so it is one hairline at every rail width.
 *
 * No component renders this alone — it is the drawing inside a `<figure>` that
 * the hero owns, exactly as the isometric plate was before it.
 */
export function TokenRidge({
  days,
  className,
  ...props
}: { days: readonly DailyTokens[] } & React.ComponentProps<"svg">) {
  const ridge = buildTokenRidge(days);
  if (!ridge.line) return null;

  return (
    <svg
      viewBox={`0 0 ${RIDGE_VIEWBOX.width} ${RIDGE_VIEWBOX.height}`}
      preserveAspectRatio="none"
      aria-hidden="true"
      className={cn("text-foreground select-none", className)}
      {...props}
    >
      {/* Mixed off the ink and the page so the tint follows the theme rather
          than naming a colour of its own. */}
      <path
        d={ridge.area}
        fill="color-mix(in oklab, var(--foreground) 9%, var(--background))"
      />
      <path
        d={ridge.line}
        fill="none"
        stroke="currentColor"
        strokeOpacity={0.45}
        strokeWidth={1}
        strokeLinejoin="round"
        strokeLinecap="round"
        vectorEffect="non-scaling-stroke"
      />
      {/* The mass has to stand on something. Without this the fill just stops
          where the plate's padding starts, and a silhouette that stops rather
          than rests reads as a crop. */}
      <line
        x1={0}
        y1={RIDGE_VIEWBOX.height}
        x2={RIDGE_VIEWBOX.width}
        y2={RIDGE_VIEWBOX.height}
        stroke="currentColor"
        strokeOpacity={0.45}
        strokeWidth={1}
        vectorEffect="non-scaling-stroke"
      />
    </svg>
  );
}

/** What the silhouette says out loud, for a reader who cannot see it. */
export function tokenRidgeDescription(days: readonly DailyTokens[]): string {
  const ridge = buildTokenRidge(days);
  if (!ridge.line) return "";
  return `Daily token use across the ${ridge.span.days} days from ${ridge.span.from} to ${ridge.span.to}, drawn as a smoothed range. Exact daily figures are in the token activity grid below.`;
}
