import type { DailyTokens } from "@/lib/ai-activity";

/**
 * The hero figure, as data.
 *
 * Raw daily token counts do not draw a mountain range — they draw one tower
 * and a plain. A single 633M afternoon against a hundred ordinary days is a
 * spike four times the height of everything around it, and a silhouette scaled
 * to hold it is a silhouette in which nothing else is visible. So the series is
 * smoothed before it is drawn, and the smoothing is stated rather than hidden:
 * the exact daily numbers are one panel further down, in Fig. 2, where they are
 * read one cell at a time.
 *
 * One window, not two. A second range behind the first is a picture of depth
 * rather than a reading of the record, and two flat greys stacked in a plate
 * this size read as one muddy grey — the figure is stronger as a single
 * silhouette at a stated resolution.
 */

/** Days folded into each ridge sample. */
export const RIDGE_SMOOTHING = 15.2;

/**
 * The drawing's own coordinate space. It is normalised rather than physical —
 * the plate stretches it to whatever width the rail happens to be, and the one
 * line that must not stretch with it carries `vector-effect`.
 */
export const RIDGE_VIEWBOX = { width: 1000, height: 100 } as const;

/** Space above the tallest ridge, so the peak is cut by nothing. */
const HEADROOM = 1.06;

/**
 * Heights are square-rooted before they are drawn.
 *
 * Between a quiet week and a loud one this record moves by two orders of
 * magnitude, and on a linear silhouette that is one wall on the right and a
 * flat floor everywhere else — half the width sits under a twentieth of the
 * peak and simply is not visible. Rooting the heights is the same move the eye
 * already makes with area: it keeps the order of every day intact, it cannot
 * turn a small day into a large one, and it gives the quiet months a shape
 * instead of a line. This is a drawing without an axis; Fig. 2 is where the
 * quantities are read, and it is linear.
 */
function relief(tokens: number): number {
  return Math.sqrt(Math.max(0, tokens));
}

/**
 * A triangular kernel, normalised, over a possibly fractional window.
 *
 * A box filter of the same width leaves flat tops and square shoulders; a
 * triangle is a box convolved with itself, and it is the cheapest kernel that
 * produces a slope a reader will accept as terrain. The width is allowed to be
 * fractional so the window can be stated as a number rather than rounded to
 * the nearest odd integer.
 */
function triangularKernel(window: number): number[] {
  const half = window / 2;
  const reach = Math.max(1, Math.ceil(half) - 1);
  const weights: number[] = [];
  let total = 0;
  for (let k = -reach; k <= reach; k += 1) {
    const w = Math.max(0, 1 - Math.abs(k) / half);
    weights.push(w);
    total += w;
  }
  return weights.map((w) => w / total);
}

/**
 * A centred smoothing that loses nothing off either end.
 *
 * Mass that would fall outside the series is folded back onto the mirrored day
 * instead of being dropped, so the smoothed series sums to exactly what the raw
 * one did. A filter that leaks at the edges quietly reports the first and last
 * weeks of the record as quieter than they were, which is the one part of this
 * figure a reader is most likely to be looking at.
 */
export function smoothSeries(
  values: readonly number[],
  window = RIDGE_SMOOTHING,
): number[] {
  if (values.length === 0) return [];
  if (values.length < window || window <= 1) return [...values];

  const weights = triangularKernel(window);
  const reach = (weights.length - 1) / 2;
  const out = new Array<number>(values.length).fill(0);

  for (let i = 0; i < values.length; i += 1) {
    const mass = Math.max(0, values[i]!);
    if (mass === 0) continue;
    for (let k = -reach; k <= reach; k += 1) {
      let j = i + k;
      if (j < 0) j = -j - 1;
      else if (j >= values.length) j = 2 * values.length - j - 1;
      if (j < 0 || j >= values.length) continue;
      out[j] += mass * weights[k + reach]!;
    }
  }
  return out;
}

export type TokenRidge = {
  /** The ridge line itself, open. */
  line: string;
  /** The same line closed down to the floor, for the fill. */
  area: string;
  /** What the smoothing is a smoothing *of*, for the accessible name. */
  span: { from: string; to: string; days: number };
};

function round(n: number): number {
  return Math.round(n * 10) / 10;
}

/**
 * Indices at a fixed stride, first and last always kept.
 *
 * A curve smoothed over a fortnight carries no detail at a two-day spacing, so
 * sampling it there discards bytes rather than information — and the path is
 * inlined into the document, where those bytes are the whole cost of the figure.
 */
function strided(length: number, stride: number): number[] {
  const out: number[] = [];
  for (let i = 0; i < length; i += stride) out.push(i);
  if (out[out.length - 1] !== length - 1) out.push(length - 1);
  return out;
}

/**
 * A monotone cubic through the sampled points (Fritsch–Carlson).
 *
 * A plain cubic spline is smoother still, but it overshoots: it invents a peak
 * above the highest day it was given and a trough below the lowest, and on a
 * series whose floor is a real zero that draws negative token use. Monotone
 * interpolation cannot leave the interval between two neighbours, so every
 * point on this curve is bounded by measurements on either side of it.
 */
function monotonePath(xs: readonly number[], ys: readonly number[]): string {
  const n = ys.length;
  if (n < 2) return "";

  const secant = new Array<number>(n - 1);
  for (let i = 0; i < n - 1; i += 1) {
    secant[i] = (ys[i + 1]! - ys[i]!) / (xs[i + 1]! - xs[i]!);
  }

  const slope = new Array<number>(n);
  slope[0] = secant[0]!;
  slope[n - 1] = secant[n - 2]!;
  for (let i = 1; i < n - 1; i += 1) {
    slope[i] = (secant[i - 1]! + secant[i]!) / 2;
  }

  for (let i = 0; i < n - 1; i += 1) {
    const d = secant[i]!;
    if (d === 0) {
      slope[i] = 0;
      slope[i + 1] = 0;
      continue;
    }
    const a = slope[i]! / d;
    const b = slope[i + 1]! / d;
    const magnitude = a * a + b * b;
    if (magnitude > 9) {
      const t = 3 / Math.sqrt(magnitude);
      slope[i] = t * a * d;
      slope[i + 1] = t * b * d;
    }
  }

  let path = `M${round(xs[0]!)},${round(ys[0]!)}`;
  for (let i = 0; i < n - 1; i += 1) {
    const h = xs[i + 1]! - xs[i]!;
    const c1x = xs[i]! + h / 3;
    const c1y = ys[i]! + (slope[i]! * h) / 3;
    const c2x = xs[i + 1]! - h / 3;
    const c2y = ys[i + 1]! - (slope[i + 1]! * h) / 3;
    path += `C${round(c1x)},${round(c1y)} ${round(c2x)},${round(c2y)} ${round(xs[i + 1]!)},${round(ys[i + 1]!)}`;
  }
  return path;
}

export function buildTokenRidge(days: readonly DailyTokens[]): TokenRidge {
  const { width: W, height: H } = RIDGE_VIEWBOX;
  const empty: TokenRidge = {
    line: "",
    area: "",
    span: { from: "", to: "", days: 0 },
  };
  if (days.length < 2) return empty;

  // The figure draws the record, and the record starts when it starts. Days
  // before the first measured token are not a quiet stretch of terrain to be
  // rendered flat — they are days this person had not begun, and giving a
  // third of the plate to them buys an empty corner at the cost of every
  // month that actually happened.
  const opened = days.findIndex((day) => day.tokens > 0);
  if (opened < 0 || days.length - opened < 2) return empty;
  const record = days.slice(opened);

  const raw = record.map((day) => day.tokens);
  const ridge = smoothSeries(raw, RIDGE_SMOOTHING).map(relief);

  const peak = Math.max(...ridge);
  // A record with nothing in it is drawn as nothing, not as a flat line at an
  // arbitrary height — the fallback for no data is no figure.
  if (peak <= 0) return empty;

  const scale = H / (peak * HEADROOM);
  const step = W / (ridge.length - 1);

  const idx = strided(ridge.length, 2);
  const line = monotonePath(
    idx.map((i) => i * step),
    idx.map((i) => H - ridge[i]! * scale),
  );

  return {
    line,
    area: `${line}L${W},${H}L0,${H}Z`,
    span: {
      from: record[0]!.date,
      to: record[record.length - 1]!.date,
      days: record.length,
    },
  };
}
