46	 * one behind it without any depth sorting.
47	 */
48	const SLABS: readonly Slab[] = [
49	  { x0: 0, y0: 0, x1: 3, y1: 1, lift: 1.2, thick: 0.4 },
50	  { x0: 2, y0: 2, x1: 7, y1: 3, lift: 0.6, thick: 0.4 },
51	  { x0: 5, y0: 4, x1: 11, y1: 5, lift: 0, thick: 0.4 },
52	];
53	
54	function SlabShape({ slab }: { slab: Slab }) {
55	  const { x0, y0, x1, y1, lift, thick } = slab;
56	  const back = corner(x0, y0, lift);
57	  const right = corner(x1 + 1, y0, lift);
58	  const front = corner(x1 + 1, y1 + 1, lift);
59	  const left = corner(x0, y1 + 1, lift);
60	  const drop = thick * EDGE;
61	  const down = ([x, y]: [number, number]): [number, number] => [x, y + drop];
62	
63	  return (
64	    <g stroke="currentColor" strokeWidth={0.6} strokeLinejoin="round">
65	      <polygon
66	        points={points([left, front, down(front), down(left)])}
67	        fill="var(--background)"
68	        strokeOpacity={0.55}
69	      />
70	      <polygon
71	        points={points([front, right, down(right), down(front)])}
72	        fill="var(--background)"
73	        strokeOpacity={0.35}
74	      />
75	      <polygon
76	        points={points([back, right, front, left])}
77	        fill="url(#site-figure-hatch)"
78	        strokeOpacity={0.7}
79	      />
80	    </g>
81	  );
82	}
83	
84	/** Generous enough that every line leaves the viewBox rather than ending in it. */
85	const FLOOR = { lo: -8, hi: 20, centre: 6 };
86	
87	function FloorLattice() {
88	  const lines: Array<[[number, number], [number, number], number]> = [];
89	  for (let n = FLOOR.lo; n <= FLOOR.hi; n += 1) {
90	    // Fade with distance from the figure so the cut ends are already faint.
91	    const fade = Math.max(
92	      0,
93	      1 - Math.abs(n - FLOOR.centre) / (FLOOR.hi - FLOOR.lo) / 0.55,
94	    );
95	    if (fade === 0) continue;
96	    lines.push([
97	      corner(FLOOR.lo, n, -0.4),
98	      corner(FLOOR.hi, n, -0.4),
99	      fade,
100	    ]);
101	    lines.push([
102	      corner(n, FLOOR.lo, -0.4),
103	      corner(n, FLOOR.hi, -0.4),
104	      fade,
105	    ]);
106	  }
107	
108	  return (
109	    <g stroke="currentColor" strokeWidth={0.5}>
110	      {lines.map(([[x1, y1], [x2, y2], fade], i) => (
111	        <line
112	          key={i}
113	          x1={round(x1)}
114	          y1={round(y1)}
115	          x2={round(x2)}
116	          y2={round(y2)}
117	          strokeOpacity={round(0.16 * fade)}
118	        />
119	      ))}
120	    </g>
121	  );
122	}
123	
124	export function SiteFigure({
125	  className,
126	  ...props
127	}: React.ComponentProps<"svg">) {
128	  return (
129	    <svg
130	      viewBox="-193 -34 490 232"
131	      // Cover, don't letterbox. The plate is a window onto a larger drawing,
132	      // so the lattice runs to all four edges and is cut there.
133	      preserveAspectRatio="xMidYMid slice"
134	      className={cn("text-foreground", className)}
135	      aria-hidden="true"
136	      {...props}
137	    >
138	      <defs>
139	        {/* Hatching on the 30° axis, so the shading is made of the same lines
140	            as everything else on the page. */}
141	        <pattern
142	          id="site-figure-hatch"
143	          width="5"
144	          height="5"
145	          patternUnits="userSpaceOnUse"
146	          patternTransform="rotate(-30)"
147	        >
148	          <line
149	            x1="0"
150	            y1="0"
151	            x2="0"
152	            y2="5"
153	            stroke="currentColor"
154	            strokeWidth="0.6"
155	            strokeOpacity="0.3"
156	          />
157	        </pattern>
158	      </defs>
159	
160	      <FloorLattice />
161	      {SLABS.map((slab) => (
162	        <SlabShape key={`${slab.x0}-${slab.y0}-${slab.lift}`} slab={slab} />
163	      ))}
164	    </svg>
165	  );
166	}
