1	/**
2	 * Published AI Activity payload (nightly → Vercel Blob).
3	 * Public-safe: daily combined token totals only.
4	 */
5	export type AiActivityPayload = {
6	  version: 1;
7	  generatedAt: string;
8	  timezone: string;
9	  /** Complete days only (through yesterday in `timezone`). */
10	  days: { date: string; tokens: number }[];
11	  lifetimeTokens: number;
12	};
13	
14	export const AI_ACTIVITY_TIMEZONE = "Asia/Kolkata";
15	export const AI_ACTIVITY_BLOB_PATH = "ai-activity/latest.json";
16	export const AI_ACTIVITY_MAX_DAYS = 800;
17	const MAX_GENERATED_AT_LEN = 40;
18	const MAX_TIMEZONE_LEN = 64;
19	
20	export function isValidIanaTimeZone(timeZone: string): boolean {
21	  if (
22	    timeZone.length < 1 ||
23	    timeZone.length > MAX_TIMEZONE_LEN ||
24	    timeZone !== timeZone.trim()
25	  ) {
26	    return false;
27	  }
28	  try {
29	    Intl.DateTimeFormat("en-US", { timeZone });
30	    return true;
31	  } catch {
32	    return false;
33	  }
34	}
35	
36	export function isAiActivityPayload(value: unknown): value is AiActivityPayload {
37	  if (!value || typeof value !== "object") return false;
38	  const v = value as Record<string, unknown>;
39	  if (v.version !== 1) return false;
40	  if (
41	    typeof v.generatedAt !== "string" ||
42	    v.generatedAt.length === 0 ||
43	    v.generatedAt.length > MAX_GENERATED_AT_LEN
44	  ) {
45	    return false;
46	  }
47	  if (typeof v.timezone !== "string" || !isValidIanaTimeZone(v.timezone)) {
48	    return false;
49	  }
50	  if (
51	    typeof v.lifetimeTokens !== "number" ||
52	    !Number.isFinite(v.lifetimeTokens) ||
53	    v.lifetimeTokens < 0
54	  ) {
55	    return false;
56	  }
57	  if (!Array.isArray(v.days)) return false;
58	  if (v.days.length === 0 || v.days.length > AI_ACTIVITY_MAX_DAYS) return false;
59	
60	  const seen = new Set<string>();
61	  for (const day of v.days) {
62	    if (!day || typeof day !== "object") return false;
63	    const date = (day as { date?: unknown }).date;
64	    const tokens = (day as { tokens?: unknown }).tokens;
65	    if (typeof date !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
66	      return false;
67	    }
68	    if (seen.has(date)) return false;
69	    seen.add(date);
70	    if (
71	      typeof tokens !== "number" ||
72	      !Number.isFinite(tokens) ||
73	      tokens < 0
74	    ) {
75	      return false;
76	    }
77	  }
78	  return true;
79	}
80	
81	export function parseAiActivityPayload(
82	  value: unknown,
83	): AiActivityPayload | null {
84	  return isAiActivityPayload(value) ? value : null;
85	}
86	
87	/** Reject payloads whose days extend past yesterday in the payload timezone. */
88	export function payloadDaysWithinHistory(
89	  payload: AiActivityPayload,
90	  now = new Date(),
91	): boolean {
92	  const cutoff = yesterdayInTimeZone(now, payload.timezone);
93	  return payload.days.every((d) => d.date <= cutoff);
94	}
95	
96	/** Calendar YYYY-MM-DD in a timezone. */
97	export function calendarDateInTimeZone(date: Date, timeZone: string): string {
98	  return new Intl.DateTimeFormat("en-CA", {
99	    timeZone,
100	    year: "numeric",
101	    month: "2-digit",
102	    day: "2-digit",
103	  }).format(date);
104	}
105	
106	/** Shift a YYYY-MM-DD by whole calendar days (noon-UTC probe). */
107	export function shiftYmd(date: string, deltaDays: number): string {
108	  const [y, m, d] = date.split("-").map(Number);
109	  const utcNoon = new Date(Date.UTC(y!, m! - 1, d!, 12, 0, 0));
110	  utcNoon.setUTCDate(utcNoon.getUTCDate() + deltaDays);
111	  return calendarDateInTimeZone(utcNoon, "UTC");
112	}
113	
114	/** First day of the month a date falls in. */
115	/** Day of week (0 = Sunday) for a YYYY-MM-DD calendar date. */
116	export function weekdayIndex(date: string): number {
117	  const [y, m, d] = date.split("-").map(Number);
118	  return new Date(Date.UTC(y!, m! - 1, d!, 12)).getUTCDay();
119	}
120	
121	export function startOfMonth(date: string): string {
122	  return `${date.slice(0, 7)}-01`;
123	}
124	
125	/** Same day-of-month `deltaMonths` away, clamped to the 1st. */
126	export function shiftMonth(date: string, deltaMonths: number): string {
127	  const [y, m] = date.split("-").map(Number);
128	  const total = y! * 12 + (m! - 1) + deltaMonths;
129	  const year = Math.floor(total / 12);
130	  const month = total - year * 12 + 1;
131	  return `${String(year).padStart(4, "0")}-${String(month).padStart(2, "0")}-01`;
132	}
133	
134	/** Previous calendar day (YYYY-MM-DD) in a timezone. */
135	export function yesterdayInTimeZone(now: Date, timeZone: string): string {
136	  return shiftYmd(calendarDateInTimeZone(now, timeZone), -1);
137	}
