1	import {
2	  AI_ACTIVITY_TIMEZONE,
3	  calendarDateInTimeZone,
4	  type AiActivityPayload,
5	  shiftYmd,
6	  weekdayIndex,
7	} from "@/lib/ai-activity-payload";
8	
9	export type DailyTokens = {
10	  date: string;
11	  tokens: number;
12	};
13	
14	export type Intensity = 0 | 1 | 2 | 3 | 4;
15	
16	export type ActivityDay = DailyTokens & {
17	  intensity: Intensity;
18	};
19	
20	/**
21	 * The four numbers under the title. One total is a milestone and says nothing
22	 * about whether the habit is still alive; four nested windows say the same
23	 * thing the grid says, in figures, for the Visitor who reads numbers before
24	 * pictures. All but the first are sums of the drawn series, so they can never
25	 * disagree with the cells above them.
26	 */
27	export type ActivityTotals = {
28	  /** All-time, from the payload — not the sum of the drawn window. */
29	  lifetime: number;
30	  days30: number;
31	  days7: number;
32	  today: number;
33	};
34	
35	export type AiActivity = {
36	  days: ActivityDay[];
37	  /** All-time total, from the payload — not the sum of the drawn window. */
38	  lifetimeTokens: number;
39	  totals: ActivityTotals;
40	  timezone: string;
41	};
42	
43	export type AiActivitySource = "blob" | "fallback";
44	
45	/**
46	 * Four filled steps, cut at the quartiles of the days that had any work in
47	 * them — not at quarters of the busiest day.
48	 *
49	 * A single 400M-token afternoon against 140 ordinary days is what a scale
50	 * measured off the maximum draws: one black square and a grey field. Cutting
51	 * at the quartiles spends the four steps on the days there actually are, so
52	 * the grid reads as a distribution rather than as one outlier and its
53	 * shadow.
54	 */
55	export type IntensityThresholds = readonly [number, number, number];
56	
57	export function quartileThresholds(
58	  days: readonly DailyTokens[],
59	): IntensityThresholds {
60	  const positive = days
61	    .map((day) => day.tokens)
62	    .filter((tokens) => tokens > 0)
63	    .sort((a, b) => a - b);
64	  if (positive.length === 0) return [0, 0, 0];
65	  const at = (ratio: number) =>
66	    positive[
67	      Math.min(positive.length - 1, Math.floor(positive.length * ratio))
68	    ]!;
69	  return [at(0.25), at(0.5), at(0.75)];
70	}
71	
72	export function intensityFromTokens(
73	  tokens: number,
74	  thresholds: IntensityThresholds,
75	): Intensity {
76	  if (tokens <= 0) return 0;
77	  if (tokens <= thresholds[0]) return 1;
78	  if (tokens <= thresholds[1]) return 2;
79	  if (tokens <= thresholds[2]) return 3;
80	  return 4;
81	}
82	
83	/**
84	 * The frame is a fixed year, and it does not move.
85	 *
86	 * An earlier version chose the window from the record — walk back for as long
87	 * as each month was worked in, stop at the first that was not — which meant the
88	 * figure was a different shape every month and a different shape again on the
89	 * day a quiet month rolled out of it. A measure whose axis changes with what it
90	 * measures is not a measure. So the grid is a calendar: fifty-two weeks back
91	 * from today, Sunday-aligned, exactly as the reference and every graph like it
92	 * draws one. The months before the habit existed are drawn empty, which is what
93	 * they were, and the record reads as having started rather than as having been
94	 * cropped.
95	 */
96	export const ACTIVITY_WEEKS = 52;
97	
98	/**
99	 * The Sunday that opens the window: this week's Sunday, then fifty-two Sundays
100	 * back from it.
101	 *
102	 * Counting whole weeks off the current week — rather than counting 364 days
103	 * back from today and rounding — is what makes the plate exactly 53 columns on
104	 * every day of every week. Counting days puts a Saturday at exactly 52 columns
105	 * and every other day at 53, and a figure that loses a column once a week is a
106	 * figure that moves under the Visitor.
107	 */
108	export function activityWindowStart(
109	  today: string,
110	  weeks = ACTIVITY_WEEKS,
111	): string {
112	  return shiftYmd(today, -(weekdayIndex(today) + weeks * 7));
113	}
114	
115	/**
116	 * Expand a sparse series into consecutive calendar days from `start` to `end`.
117	 *
118	 * Inside this window an absent day is a measured zero, not a hole: the meter
119	 * reads every local session on the machine, so a day it never mentions is a
120	 * day nothing ran. The one genuinely unknown day is today, which the nightly
121	 * sync has not reached yet — and today's zero is drawn as the emptiest step,
122	 * which is what it is.
123	 */
124	export function buildDailySeries(
125	  days: readonly DailyTokens[],
126	  start: string,
127	  end: string,
128	): DailyTokens[] {
129	  const byDate = new Map(days.map((day) => [day.date, day.tokens]));
130	  const series: DailyTokens[] = [];
131	  for (let cursor = start; cursor <= end; cursor = shiftYmd(cursor, 1)) {
132	    series.push({ date: cursor, tokens: byDate.get(cursor) ?? 0 });
133	  }
134	  return series;
135	}
136	
137	/** Sum of the last `count` days of a consecutive series ending today. */
138	function sumTrailing(days: readonly DailyTokens[], count: number): number {
139	  return days
140	    .slice(-count)
141	    .reduce((total, day) => total + Math.max(0, day.tokens), 0);
142	}
143	
144	export function buildAiActivity(
145	  series: readonly DailyTokens[],
146	  options?: { timezone?: string; lifetimeTokens?: number },
147	): AiActivity {
148	  const thresholds = quartileThresholds(series);
149	  const lifetimeTokens =
150	    options?.lifetimeTokens ??
151	    series.reduce((sum, day) => sum + day.tokens, 0);
152	
153	  return {
154	    days: series.map((day) => ({
155	      ...day,
156	      intensity: intensityFromTokens(day.tokens, thresholds),
157	    })),
158	    lifetimeTokens,
159	    totals: {
160	      lifetime: lifetimeTokens,
161	      days30: sumTrailing(series, 30),
162	      days7: sumTrailing(series, 7),
163	      today: sumTrailing(series, 1),
164	    },
165	    timezone: options?.timezone ?? AI_ACTIVITY_TIMEZONE,
166	  };
167	}
168	
169	export function materializeAiActivity(
170	  payload: AiActivityPayload,
171	  now = new Date(),
172	): AiActivity {
173	  const timezone = payload.timezone || AI_ACTIVITY_TIMEZONE;
174	  const today = calendarDateInTimeZone(now, timezone);
175	  const start = activityWindowStart(today);
176	
177	  return buildAiActivity(buildDailySeries(payload.days, start, today), {
178	    timezone,
179	    lifetimeTokens: payload.lifetimeTokens,
180	  });
181	}
182	
183	/** Exact count. Used where a number is a number: alt text, tests, scripts. */
184	export function formatTokenCount(tokens: number): string {
185	  return new Intl.NumberFormat("en-US").format(tokens);
186	}
187	
188	/**
189	 * The number as it is read aloud: `10.4B`, `512M`, `84.2K`. Ten billion is
190	 * eleven digits, and eleven digits is a serial number, not a quantity — the
191	 * page wants the magnitude, and the magnitude is the first three characters.
192	 */
193	export function formatCompactTokens(tokens: number): string {
194	  const value = Math.max(0, Math.round(tokens));
195	  for (const [limit, suffix] of [
196	    [1e12, "T"],
197	    [1e9, "B"],
198	    [1e6, "M"],
199	    [1e3, "K"],
200	  ] as const) {
201	    if (value >= limit) {
202	      const scaled = value / limit;
203	      return `${scaled >= 100 ? Math.round(scaled) : Number(scaled.toFixed(1))}${suffix}`;
204	    }
205	  }
206	  return String(value);
207	}
